(128,"Why bootstrapped critics lower variance?","They replace the noisy full return with r + γV(s'), at the cost of bias from V's errors."),
(131,"Why audit agent behaviour, not just reward?","High reward can come from exploits; only inspecting trajectories reveals hacking."),
(137,"Retrieval-as-a-tool recall@1 on Day 137?","0.48."),
